"""Ipsec utils"""
from builtins import object
import re
from subprocess import CalledProcessError
from taf.ul.trs_e2e_fw.lib.ipsec.exceptions import IpSecStateError
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator
from taf.ul.trs_e2e_fw.lib.utils.front_haul_modules.rf_module.rf_module import RfModule
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()


class ipsec_utils(object):
    """Ipsec utils"""
    def __init__(self):
        self.config = ConfigHandler.get_config()

    def execute_command_on_secgw(self, cmd, device):
        """Executes command on secgw"""
        ip = get_config_variable(["ipsec_devices", device, "ip"])
        user = get_config_variable(["ipsec_devices", device, "user"])
        password = get_config_variable(["ipsec_devices", device, "password"])
        logger.debug("Command being executed on secure gateway: {}".format(cmd))
        return Communicator().execute_command_remotely_and_verify(ip, user, password, cmd)

    def execute_command_on_bts(self, cmd, device):
        """Executes command on bts"""
        ip = get_config_variable([device, "ip"])
        user = get_config_variable([device, "user"])
        password = get_config_variable([device, "password"])
        logger.debug("Command being executed on BTS: {}".format(cmd))
        return Communicator().execute_command_remotely_and_verify(ip, user, password, cmd)

    def execute_command_on_rf_module(self, cmd, device, rfmod_inst_id, iprange):
        """Executes command on rf module"""
        rf_module = RfModule()
        try:
            rf_module.rfmodule_setup(config_device=device, rfmod_inst_id=rfmod_inst_id, iprange=iprange,
                                     fhnet_login_only=True, alias='internal_call')
            return rf_module.send_cmd_recv_output(cmd=cmd, timeout=5,
                                                  prompt=get_config_variable([device, "fhnet_prompt"]),
                                                  alias='internal_call')
        except Exception as e:
            Exception("Caught exception :: {}".format(e))
        finally:
            rf_module.rfmodule_teardown(alias='internal_call')

    def parse_connections_states(self, connections, console_output):
        """Parse connection states"""
        connection_status_dictionary = {}
        for connection_number in connections:
            connection_status, connection_espspi = self.parse_state(connection_number, console_output)
            connection_status_dictionary[connection_number] = (connection_status, connection_espspi)
        return connection_status_dictionary

    def parse_state(self, connection_number, console_output):
        """Parse state"""
        conn_stat_regex = r'conn{}.*?ESTABLISHED'.format(connection_number)
        conn_espspi_regex = r'conn{}.*?INSTALLED.*ESP SPIs: ([a-f0-9]+_i [a-f0-9]+_o)'.format(
            connection_number)
        connection_status = 'established' if re.search(conn_stat_regex, console_output) else \
            'not established'
        match = re.search(conn_espspi_regex, console_output)
        connection_espspi = match.group(1) if match else None
        return connection_status, connection_espspi

    def assert_state(self, expected_state, found_state):
        """Assert state"""
        if found_state != expected_state.strip().lower():
            raise IpSecStateError('Expecting {} , but found {}'.format(expected_state,
                                                                       found_state))

    def verify_ipsec_status_output(self, cmd, output):
        if output is None or len(output.splitlines()) <= 2:
            raise CalledProcessError(1, cmd, output)
